(()=>{
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let snapshot={pairs:[],updatedAt:0},count=20,busy=false,error='',universe=[];
const cash=x=>Number.isFinite(Number(x))?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:Number(x)>10000?'compact':'standard',maximumSignificantDigits:4}).format(Number(x)):'—';
function ranked(){const map=new Map();for(const p of snapshot.pairs){if(p.chainId!=='robinhood'||!/^0x(?:[\da-f]{40}|[\da-f]{64})$/i.test(p.pairAddress)||!p.baseToken?.address)continue;const old=map.get(p.baseToken.address);if(!old||Number(p.liquidity?.usd||0)>Number(old.liquidity?.usd||0))map.set(p.baseToken.address,p)}return [...map.values()].sort((a,b)=>Number(b.volume?.h24||0)-Number(a.volume?.h24||0)).slice(0,count)}
function body(){return `<div class="rh-meta"><span>${busy?'Refreshing…':error||'DexScreener · Robinhood Chain mainnet'} · ${snapshot.updatedAt?'Updated '+new Date(snapshot.updatedAt).toLocaleString():'Loading data'}</span><span>Hourly while open</span></div><div class="rh-table-wrap"><table class="rh-table"><thead><tr><th># / Token</th><th>Price</th><th>24h</th><th>24h volume</th><th>Liquidity</th><th></th></tr></thead><tbody>${ranked().map((p,i)=>`<tr><td><div class="rh-token"><span class="rank">${String(i+1).padStart(2,'0')}</span>${CanopyUI.meme(p)}<span><b>${esc(p.baseToken.symbol)}</b><small>${esc(p.baseToken.name)}</small></span></div></td><td>${cash(p.priceUsd)}</td><td class="${Number(p.priceChange?.h24)>=0?'positive':'negative'}">${p.priceChange?.h24==null?'—':esc(Number(p.priceChange.h24).toFixed(2))+'%'}</td><td>${cash(p.volume?.h24)}</td><td>${cash(p.liquidity?.usd)}</td><td><a class="quiet" target="_blank" rel="noopener" href="https://dexscreener.com/robinhood/${p.pairAddress}" aria-label="Open ${esc(p.baseToken.symbol)} on DexScreener">Chart <svg class="outbound-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 11 11 5M5 5h6v6"/></svg></a></td></tr>`).join('')||'<tr><td colspan="6">No market data available. Try refresh.</td></tr>'}</tbody></table></div>`}
function paint(){const el=document.querySelector('#rh-data');if(el)el.innerHTML=body()}
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error('Data unavailable');return r.json()}
async function refresh(){if(busy)return;busy=true;paint();try{if(!universe.length)universe=(await json('data/rh-universe.json')).tokens;const discovery=await Promise.allSettled([json('https://api.dexscreener.com/token-profiles/latest/v1'),json('https://api.dexscreener.com/latest/dex/search?q=robinhood')]);const extra=[...(discovery[0].status==='fulfilled'&&Array.isArray(discovery[0].value)?discovery[0].value.filter(x=>x.chainId==='robinhood').map(x=>x.tokenAddress):[]),...(discovery[1].status==='fulfilled'?discovery[1].value.pairs||[]:[]).filter(x=>x.chainId==='robinhood').map(x=>x.baseToken?.address)];const addresses=[...new Set([...universe.map(x=>x.address),...extra].filter(x=>/^0x[\da-f]{40}$/i.test(x)))].slice(0,90);const chunks=[];for(let i=0;i<addresses.length;i+=30)chunks.push(addresses.slice(i,i+30));const pairs=(await Promise.all(chunks.map(c=>json('https://api.dexscreener.com/tokens/v1/robinhood/'+c.join(','))))).flat();if(!Array.isArray(pairs)||!pairs.length)throw Error('Empty data');snapshot={updatedAt:Date.now(),pairs};try{localStorage.setItem('canopy-rh',JSON.stringify(snapshot))}catch{}error=''}catch{error='Refresh unavailable · showing last snapshot'}finally{busy=false;paint()}}
window.CanopyRH={view:()=>`<div class="page-heading"><div><div class="eyebrow">ROBINHOOD CHAIN</div><h1>Meme market.</h1><p class="subtitle">The busiest pools in our RH meme watchlist.</p></div><a class="secondary" href="https://dexscreener.com/robinhood" target="_blank" rel="noopener">Explore all on DexScreener <svg class="outbound-icon" viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 11 11 5M5 5h6v6"/></svg></a></div><div class="rh-summary"><div><span class="label">VOLUME LEADERS</span><h2>RH meme watchlist</h2><p>Ranked by 24-hour trading volume across our tracked tokens. The most liquid pool represents each token.</p></div><div class="rh-summary-number">${count}<span>on the radar</span></div></div><div class="card-top rh-controls"><div class="segments"><button id="rh10" class="${count===10?'active':''}">Top 10</button><button id="rh20" class="${count===20?'active':''}">Top 20</button></div><span class="auto-refresh-label"><span class="auto-refresh-dot"></span>Auto-refresh on</span></div><section id="rh-data">${body()}</section><p class="form-note">Seeded watchlist plus public token discovery; coverage is not exhaustive. This is not DexScreener’s proprietary trending leaderboard. These are mainnet market data, separate from the testnet workspace. Tokens are not endorsements.</p>`,mount:()=>{for(const n of [10,20])document.querySelector('#rh'+n).onclick=()=>{count=n;render()};if(Date.now()-snapshot.updatedAt>3600000)refresh()}};
(async()=>{try{let cached;try{cached=JSON.parse(localStorage.getItem('canopy-rh'))}catch{}snapshot=cached?.pairs?cached:await json('data/rh-snapshot.json');paint();if(location.hash==='#rh')refresh()}catch{error='Unable to load snapshot';paint()}})();setInterval(refresh,3600000);document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-snapshot.updatedAt>3600000)refresh()});if(location.hash==='#rh')render();
})();
